'use strict';
function buildPolicies({event:E,option:O,later:L}){
const P=(name,effect)=>({name,effect,years:3});
return [
E(3,'Hướng đi ba năm đầu','Nguồn lực có hạn. Ba năm đầu, chiến lược quốc gia sẽ ưu tiên mở rộng năng lực sản xuất hay nâng nền an sinh trước?',O('Ưu tiên tích lũy và đầu tư',[-8,14,-8,-6],'Nguồn lực nghiêng về sản xuất; nhóm thu nhập thấp chờ lâu hơn để hưởng thành quả.',null,P('Ưu tiên tích lũy',[-2,4,-2,1])),O('Ưu tiên nền an sinh',[12,-6,12,-13],'Nhu cầu thiết yếu được đáp ứng sớm; nguồn lực đầu tư và ngân sách chịu sức ép.',null,P('Nền an sinh',[3,-1,3,-4]))),
E(3,'Cải cách thuế thu nhập','Thu nhập tăng tập trung ở nhóm trên. Cần chọn cách huy động nguồn lực cho dịch vụ công trong ba năm tới.',O('Tăng điều tiết thu nhập cao',[2,-7,13,12],'Phân phối lại mạnh hơn; trong mô hình này, phần lợi ích giữ lại và động lực đầu tư giảm.',null,P('Thuế lũy tiến mạnh',[0,-2,2,3])),O('Giảm thuế, mở rộng cơ sở thu',[4,11,-9,-9],'Thu nhập giữ lại tăng; dịch vụ công cần chờ nguồn thu phục hồi.',L(6,[0,5,-2,8],'Cơ sở thuế mở rộng','Hoạt động kinh tế tăng đã bù lại một phần hụt thu ban đầu.'))),
E(1,'Một gói đầu tư quốc gia','Ngân sách chỉ đủ khởi động một chương trình lớn. Nút thắt ở các trung tâm xuất khẩu hay ở vùng chưa tiếp cận thị trường?',O('Hành lang công nghiệp xuất khẩu',[-3,15,-10,-14],'Tập trung vốn tạo công suất nhanh; chênh lệch vùng tăng.',L(6,[7,12,-3,9],'Hành lang đi vào vận hành','Năng lực xuất khẩu tăng, nhưng việc làm chất lượng vẫn tập trung ở các cực tăng trưởng.')),O('Hạ tầng vùng và dịch vụ cơ bản',[5,2,12,-15],'Đầu tư phân tán tiếp cận nhiều cộng đồng; thu hồi nguồn lực chậm hơn.',L(8,[9,9,7,4],'Những vùng mới kết nối','Chi phí tiếp cận thị trường giảm, nhiều hộ có thể tham gia sản xuất.'))),
E(0,'Điều chỉnh lương tối thiểu','Giá sinh hoạt đã đi trước tiền lương. Chính sách toàn quốc cần chọn tốc độ điều chỉnh cho hai năm tới.',O('Tăng nhanh để bù mức sống',[14,-11,9,-4],'Sức mua phục hồi; các doanh nghiệp năng suất thấp chịu áp lực chi phí.',L(3,[-3,-4,0,-2],'Doanh nghiệp điều chỉnh tuyển dụng','Một phần doanh nghiệp giảm tuyển mới để thích ứng với chi phí.')),O('Tăng dần, gắn với năng suất',[3,8,-7,2],'Doanh nghiệp có thời gian thích ứng; người thu nhập thấp chưa bù được chi phí sinh hoạt.',L(4,[7,6,3,3],'Lộ trình lương có kết quả','Năng suất và thu nhập cùng tăng, sau giai đoạn chờ đợi.'))),
E(3,'Sóng lạm phát','Giá đầu vào nhập khẩu tăng trên diện rộng. Giữ ổn định giá hay giữ đà hoạt động kinh tế trước?',O('Thắt chặt tín dụng',[-8,-13,4,8],'Trong kịch bản giả định, cầu và áp lực giá giảm, nhưng đầu tư và việc làm chậm lại.',L(3,[10,1,5,2],'Áp lực giá hạ nhiệt','Sức mua thực tế hồi phục sau giai đoạn hoạt động kinh tế chững lại.')),O('Giữ tín dụng, bù giá thiết yếu',[12,8,-6,-14],'Việc làm được hỗ trợ trước mắt; ngân sách và áp lực giá tiếp tục chịu sức ép.',L(4,[-9,-3,-5,-5],'Chi phí bình ổn kéo dài','Hỗ trợ chưa rút kịp khiến ngân sách mỏng đi và giá tiếp tục gây áp lực.'))),
E(2,'Ai được bảo vệ khi gặp rủi ro?','Cần thiết kế nền trợ giúp xã hội quốc gia. Phủ rộng hay tập trung ngân sách vào những người khó khăn nhất?',O('Mở rộng sàn an sinh toàn dân',[12,-3,10,-16],'Bao phủ rộng giúp giảm bỏ sót; nghĩa vụ chi thường xuyên lớn.',null,P('Sàn an sinh rộng',[3,0,2,-4])),O('Tập trung theo mức thiếu hụt',[7,1,13,-8],'Chi phí thấp hơn, nhưng hồ sơ và xác minh có thể khiến một số người bị bỏ sót.',L(4,[-4,0,-3,2],'Khoảng trống bao phủ','Một số lao động thu nhập bấp bênh không đáp ứng được tiêu chí hỗ trợ.'))),
E(4,'Đổi mới trên quy mô quốc gia','Tự động hóa đang thay đổi nhu cầu lao động. Quỹ phát triển sẽ nghiêng về công nghệ hay kỹ năng chuyển đổi?',O('Ưu đãi tự động hóa diện rộng',[-10,16,-10,-8],'Năng suất có thể tăng nhanh; lao động kỹ năng thấp đối mặt mất việc.',L(5,[4,12,-5,7],'Làn sóng công nghệ mới','Sản lượng tăng nhưng thành quả phân bổ không đều giữa các nhóm lao động.')),O('Đào tạo lại trước khi chuyển đổi',[4,-4,11,-12],'Chuyển đổi chậm hơn để nhiều người đủ khả năng tham gia.',L(5,[11,13,7,5],'Lao động bước sang ngành mới','Kỹ năng mới giúp chuyển đổi công việc và hấp thụ công nghệ.'))),
E(1,'Doanh nghiệp nhà nước thua lỗ','Một số doanh nghiệp lớn đang thua lỗ kéo dài nhưng sử dụng nhiều lao động. Ngân sách có tiếp tục bù lỗ?',O('Tái cơ cấu, hỗ trợ người mất việc',[-10,4,5,-7],'Việc làm bị xáo trộn; nguồn lực được chuyển khỏi hoạt động kém hiệu quả.',L(5,[7,10,4,10],'Nguồn lực được tái phân bổ','Chi bù lỗ giảm và một phần lao động tìm được công việc mới.')),O('Bơm vốn giữ việc làm',[9,-5,2,-17],'Việc làm hiện tại được giữ; hiệu quả thấp tiếp tục hút nguồn lực.',null,P('Duy trì bù lỗ',[1,-2,0,-4]))),
E(5,'Chiến lược an ninh lương thực','Cần chọn cách ổn định giá lương thực khi nguồn cung biến động trên diện rộng.',O('Bù giá đầu vào nông nghiệp',[7,9,3,-13],'Sản xuất được hỗ trợ nhanh; chi ngân sách có thể kéo dài.',null,P('Bù giá đầu vào',[1,2,0,-3])),O('Đầu tư dự trữ và logistics',[-3,3,5,-11],'Chưa hỗ trợ nhiều cho vụ hiện tại, nhưng giảm hao hụt lâu dài.',L(5,[12,9,5,5],'Chuỗi lương thực vững hơn','Dự trữ và vận chuyển tốt hơn làm giảm biến động nguồn hàng.'))),
E(3,'Kỷ luật tài khóa','Thâm hụt tăng. Chọn một hướng ngân sách trung hạn, mỗi hướng đều có nhóm chịu chi phí.',O('Giảm chi, phục hồi dự phòng',[-12,-8,-9,18],'Nguồn lực tài khóa hồi phục; dịch vụ và tổng cầu giảm.',null,P('Thắt chặt chi tiêu',[-2,-1,-2,4])),O('Vay cho đầu tư có chọn lọc',[3,12,3,-13],'Đầu tư tiếp tục; nghĩa vụ hoàn trả thu hẹp ngân sách tương lai.',L(6,[3,7,1,-10],'Đến kỳ trả nợ đầu tư','Công trình tạo thêm sản lượng, đồng thời khoản vay bắt đầu đến hạn.'))),
E(3,'Thuế tài sản và nguồn thu địa phương','Hạ tầng làm giá đất tăng, nhưng lợi ích tập trung ở người sở hữu. Có huy động thêm phần gia tăng này?',O('Điều tiết tài sản giá trị cao',[-2,-7,14,15],'Có thêm nguồn lực công; thị trường tài sản và đầu tư liên quan chậm lại.'),O('Giữ thuế, khuyến khích giao dịch',[7,11,-12,2],'Hoạt động thị trường sôi động hơn; chênh lệch sở hữu tiếp tục mở rộng.')),
E(0,'Chia sẻ thành quả tăng trưởng','Cần định hướng quan hệ lao động toàn quốc: tăng sức thương lượng của người làm công hay linh hoạt hóa sử dụng lao động?',O('Mở rộng thương lượng tập thể',[12,-7,12,-3],'Người lao động có tiếng nói hơn về lương và điều kiện làm việc; điều chỉnh sản xuất tốn thêm thời gian.'),O('Ưu tiên linh hoạt tuyển dụng',[-7,13,-10,3],'Doanh nghiệp thích ứng nhanh; người lao động chịu rủi ro thu nhập lớn hơn.',null,P('Thị trường lao động linh hoạt',[-1,3,-2,1]))),
E(1,'Thu hút vốn đầu tư quốc tế','Một làn sóng đầu tư mới đang tìm địa điểm. Đổi ưu đãi thuế lấy dự án nhanh, hay đòi hỏi liên kết công nghệ?',O('Ưu đãi lớn để hút dự án',[5,14,-6,-14],'Vốn và việc làm đến nhanh hơn; phần thu ngân sách và liên kết trong nước còn hạn chế.'),O('Ưu đãi gắn chuyển giao kỹ năng',[-3,4,6,-6],'Một số dự án rời đi; dự án còn lại phải tạo liên kết.',L(5,[8,12,6,7],'Nhà cung ứng nội địa trưởng thành','Kỹ năng và công nghệ lan sang doanh nghiệp trong nước.'))),
E(2,'Đô thị hóa và nhà ở','Chi phí ở tại các trung tâm kinh tế đang ăn mòn tiền lương. Chương trình nhà ở quốc gia sẽ đi theo hướng nào?',O('Xây quỹ nhà ở xã hội cho thuê',[5,4,12,-17],'Nguồn lực công lớn được dành cho khả năng tiếp cận nhà ở.',L(5,[12,4,8,0],'Quỹ nhà ở bắt đầu sử dụng','Chi phí sinh hoạt giảm với những hộ tiếp cận được nhà ở.')),O('Nới nguồn cung nhà thương mại',[3,13,-8,-3],'Đầu tư xây dựng tăng; nhóm thu nhập thấp có thể vẫn chưa đủ khả năng mua hay thuê.')),
E(3,'Chuyển nguồn thu từ đâu?','Cần tăng nguồn thu mà vẫn cân nhắc sức mua và động lực đầu tư. Chọn nền tảng thuế cho giai đoạn mới.',O('Tăng thuế tiêu dùng',[-12,-3,-11,17],'Nguồn thu tương đối rộng; nhóm thu nhập thấp chịu gánh nặng tương đối lớn hơn.'),O('Tăng thuế lợi nhuận và chống thất thu',[1,-10,10,11],'Phần lợi nhuận giữ lại giảm; nguồn lực cho phân phối lại tăng.')),
E(1,'Suy giảm thương mại toàn cầu','Đơn hàng xuất khẩu giảm mạnh. Gói ứng phó quốc gia sẽ giữ năng lực hiện có hay hỗ trợ chuyển dịch?',O('Kích cầu, giữ doanh nghiệp hoạt động',[12,11,-3,-18],'Việc làm được giữ trước mắt; có nguy cơ hỗ trợ cả hoạt động không còn khả thi.',L(4,[-2,-3,0,-6],'Đến lúc rút hỗ trợ','Doanh nghiệp còn phụ thuộc gói hỗ trợ cần tiếp tục điều chỉnh.')),O('Bảo vệ người lao động, cho tái cơ cấu',[2,-12,12,-8],'Sản lượng giảm ngay, nhưng người mất việc có lưới bảo vệ.',L(5,[7,15,4,6],'Ngành mới hấp thụ lao động','Nguồn lực chuyển dần sang các hoạt động có thị trường.'))),
E(4,'Đại học hay phổ cập kỹ năng?','Quỹ nhân lực quốc gia chỉ đủ mở rộng mạnh một hướng. Đầu tư mũi nhọn hay nâng nền kỹ năng rộng?',O('Tập trung nghiên cứu mũi nhọn',[-3,5,-8,-11],'Nguồn lực tập trung vào nhóm trình độ cao.',L(6,[4,16,-3,8],'Năng lực nghiên cứu tạo đầu ra','Một số ngành công nghệ phát triển nhanh, chênh lệch kỹ năng tăng.')),O('Phổ cập kỹ năng và học nghề',[6,2,12,-12],'Nhiều người tiếp cận kỹ năng cơ bản hơn.',L(5,[10,9,7,4],'Nền kỹ năng được nâng lên','Nhiều lao động tham gia được công việc có năng suất tốt hơn.'))),
E(5,'Tổ chức lại sản xuất nông nghiệp','Quy mô nhỏ hạn chế cơ giới hóa. Cần chọn cách nâng năng suất mà vẫn tính đến sinh kế nông hộ.',O('Tập trung đất cho sản xuất lớn',[-7,15,-11,5],'Quy mô giúp tăng năng suất; hộ rời đất cần sinh kế khác.',L(4,[-5,4,-5,-3],'Áp lực chuyển nghề nông thôn','Một bộ phận hộ chưa tìm được nguồn thu thay thế.')),O('Liên kết hợp tác xã tự nguyện',[6,5,11,-8],'Nông hộ giữ quyền tham gia; tổ chức liên kết cần thời gian.',L(5,[6,9,5,4],'Chuỗi hợp tác được củng cố','Mua chung, bán chung và tiêu chuẩn chất lượng giúp nâng hiệu quả.'))),
E(2,'Tài chính cho y tế toàn dân','Chương trình y tế cần nguồn chi lâu dài. Tăng tài trợ công hay tăng phần cùng chi trả?',O('Tăng tài trợ công, giảm viện phí',[14,-3,13,-16],'Rủi ro chi phí y tế được chia sẻ rộng hơn.',null,P('Mở rộng tài trợ y tế',[2,0,2,-3])),O('Tăng cùng chi trả, miễn cho hộ nghèo',[-6,4,-7,11],'Ngân sách bớt áp lực; nhóm cận nghèo có thể trì hoãn khám chữa bệnh.')),
E(3,'Phân bổ ngân sách giữa các vùng','Các trung tâm đóng góp nhiều nguồn thu, trong khi các vùng khó khăn thiếu dịch vụ và hạ tầng.',O('Điều tiết nhiều hơn cho vùng khó',[3,-8,15,-7],'Khoảng cách cơ hội giảm; vốn ở cực tăng trưởng tăng chậm.',L(5,[7,9,7,5],'Thêm vùng tham gia thị trường','Kết nối và dịch vụ tốt hơn mở rộng nền sản xuất.')),O('Cho trung tâm giữ lại nhiều nguồn thu',[4,15,-12,3],'Các cực tăng trưởng đầu tư nhanh; chênh lệch vùng lớn hơn.')),
E(1,'Cạnh tranh hay quy mô tập đoàn?','Một số thị trường tập trung cao. Cần ưu tiên kỷ luật cạnh tranh hay tạo các doanh nghiệp đầu tàu?',O('Siết lạm dụng vị thế thị trường',[7,-7,12,-4],'Giảm sức ép lên khách hàng và doanh nghiệp nhỏ; tái tổ chức có chi phí.',L(4,[4,10,4,4],'Doanh nghiệp mới gia nhập','Cơ hội tham gia mở rộng tạo thêm sức cạnh tranh.')),O('Hỗ trợ các tập đoàn đầu tàu',[3,14,-13,-7],'Quy mô tăng nhanh; quyền lực thị trường và lợi ích tập trung hơn.')),
E(3,'Phân bổ tín dụng','Nguồn vốn có giới hạn. Chọn mở rộng tiếp cận cho doanh nghiệp nhỏ hay tập trung các dự án chiến lược?',O('Bảo lãnh vốn cho doanh nghiệp nhỏ',[7,7,10,-12],'Nhiều chủ thể tiếp cận vốn; Nhà nước chịu một phần rủi ro tín dụng.',L(4,[-2,-3,0,-5],'Một số bảo lãnh phải chi trả','Một phần khoản vay không phục hồi được, ngân sách phải thực hiện cam kết.')),O('Tập trung vốn vào dự án lớn',[-4,15,-10,-5],'Quy mô đầu tư tăng; doanh nghiệp nhỏ khó tiếp cận nguồn vốn.')),
E(5,'Chuyển dịch năng lượng','Nền sản xuất cần điện ổn định và ít ô nhiễm hơn. Tốc độ chuyển đổi sẽ quyết định ai chịu chi phí trước.',O('Chuyển đổi nhanh, hỗ trợ vùng ảnh hưởng',[-7,-5,8,-15],'Chi phí chuyển đổi lớn, đồng thời hỗ trợ lao động và cộng đồng.',L(5,[10,14,5,7],'Nguồn năng lượng mới ổn định','Hiệu quả và chất lượng môi trường cải thiện sau giai đoạn đầu tư.')),O('Chuyển đổi chậm, giữ giá đầu vào',[8,12,-7,4],'Chi phí hiện tại thấp hơn, nhưng rủi ro ô nhiễm và công nghệ cũ kéo dài.',L(5,[-12,-7,-5,-8],'Chi phí bị đẩy về tương lai','Sức khỏe, khắc phục môi trường và nâng cấp muộn tạo thêm gánh nặng.'))),
E(3,'Dùng phần thu vượt dự kiến','Kinh tế phục hồi tạo nguồn thu bổ sung. Chọn củng cố sức chống chịu hay mở rộng quyền lợi ngay?',O('Trả nợ và lập quỹ dự phòng',[-3,-4,-3,17],'Có khoảng đệm cho cú sốc tiếp theo, nhưng nhu cầu xã hội chưa được đáp ứng thêm.'),O('Tăng chi dịch vụ công',[12,3,12,-10],'Dịch vụ tốt hơn, nhưng nguồn dự phòng ít đi.',null,P('Nâng chuẩn dịch vụ công',[2,1,2,-3]))),
E(4,'Ai trả cho quá trình học suốt đời?','Nhu cầu đổi nghề tiếp tục tăng. Cơ chế tài trợ sẽ đặt trọng tâm vào ngân sách hay trách nhiệm doanh nghiệp?',O('Quỹ quốc gia cho mọi người học',[7,3,12,-14],'Người ngoài khu vực chính thức cũng được tiếp cận.',L(4,[8,10,5,4],'Lực lượng lao động thích ứng','Nâng kỹ năng giúp duy trì việc làm và mở rộng cơ hội.')),O('Buộc doanh nghiệp tăng chi đào tạo',[3,-6,3,7],'Giảm gánh nặng công; doanh nghiệp chịu chi phí và người ngoài hệ thống khó tiếp cận.',L(4,[5,12,-3,3],'Kỹ năng trong doanh nghiệp tăng','Lao động chính thức tiến bộ nhanh hơn nhóm chưa có việc ổn định.'))),
E(2,'Thiên tai trên diện rộng','Nhiều vùng mất sinh kế cùng lúc. Gói phục hồi quốc gia cần lựa chọn giữa phục hồi nhanh và tái thiết thích ứng.',O('Cứu trợ và khôi phục ngay',[16,6,9,-18],'Nhu cầu trước mắt được giải quyết nhanh; rủi ro tái diễn còn lớn.'),O('Tái thiết thích ứng dài hạn',[2,-5,7,-12],'Khôi phục thu nhập chậm hơn trong lúc xây dựng lại.',L(3,[12,10,6,4],'Hạ tầng thích ứng phát huy tác dụng','Sinh kế trở lại với mức chống chịu tốt hơn.'))),
E(0,'Phân phối trong doanh nghiệp','Cần chọn cơ chế khuyến khích chia sẻ thành quả trên phạm vi nền kinh tế.',O('Ưu đãi cho chia lợi nhuận với lao động',[13,-6,12,-9],'Thu nhập lao động và sự gắn bó tăng; phần giữ lại cho đầu tư giảm.'),O('Ưu đãi cho lợi nhuận tái đầu tư',[-5,15,-9,-7],'Tích lũy tăng nhanh; người lao động chưa được hưởng phần tăng tương xứng.',L(3,[7,9,0,5],'Đầu tư mở thêm công suất','Có thêm việc làm nhưng cần thương lượng để thành quả được chia sẻ.'))),
E(1,'Rút hỗ trợ khẩn cấp','Các gói hỗ trợ đang duy trì một số hoạt động kém hiệu quả. Rút ngay hay kéo dài để tránh đứt việc làm?',O('Rút dần, hỗ trợ chuyển việc',[-9,3,5,12],'Một số việc làm mất đi; ngân sách có thêm không gian.',L(2,[6,9,3,3],'Nguồn lực dịch chuyển','Lao động và vốn chuyển sang hoạt động có khả năng tự duy trì.')),O('Gia hạn thêm một chu kỳ',[10,-5,-3,-15],'Tránh cú sốc trước mắt; gánh nặng hỗ trợ tiếp tục tồn tại.',null,P('Gia hạn cứu trợ',[1,-1,0,-4]))),
E(5,'Khoảng cách số giữa các vùng','Hạ tầng số đã có nhưng khả năng sử dụng chênh lệch. Chọn tăng tốc ngành mới hay đưa nhiều người cùng tham gia?',O('Đầu tư các trung tâm công nghệ',[-3,15,-10,-10],'Tạo thêm năng lực ngành giá trị cao; lợi ích tập trung ở nhóm sẵn kỹ năng.'),O('Phổ cập kết nối và dịch vụ số',[8,4,13,-12],'Cơ hội tiếp cận rộng hơn; hiệu quả kinh tế cần thời gian tích lũy.',L(1,[4,7,3,2],'Thêm hộ kinh doanh tham gia','Chi phí giao dịch và tiếp cận thị trường giảm.'))),
E(3,'Cam kết cho nhiệm kỳ sau','Chiếc bánh đã đổi khác sau mười năm. Bạn muốn để lại ưu tiên nào cho giai đoạn tiếp theo?',O('Bảo đảm nền sống và cơ hội',[12,-8,13,-13],'Phần nguồn lực cuối nghiêng về mức sống và cơ hội; đầu tư và dự phòng giảm.'),O('Giữ tích lũy và sức chống chịu',[-8,13,-9,14],'Nguồn lực tương lai được củng cố; nhóm hưởng lợi ít vẫn cần được quan tâm.'))
];}

